targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const authType = api.state.authType;
    const installMethod = api.state.installMethod;
    const midServerOS = api.state.midServerOS;

    var result = {
        authType: authType || null,
        installMethod: installMethod || null,
        midServerOS: midServerOS || null
    };

    return {
        pageID: 'mid-installation-plan',
        requiredParams: result,
        optionalParams: {}
    };
})

